document.addEventListener('click',e=>{
  const menu=e.target.closest('[data-selection-menu]');
  if(menu){selectionMenu(menu.dataset.selectionMenu);return}
  const format=e.target.closest('[data-selection-format]');
  if(format){applySelectionFormat(format.dataset.selectionFormat);const box=$('#selection-toolbar-menu');if(box){box.hidden=true;box.innerHTML=''}selectionMenuMode='';return}
  const color=e.target.closest('[data-selection-color]');
  if(color){const [kind,value]=color.dataset.selectionColor.split(':');if(!restoreEditorSelection())return;document.execCommand('styleWithCSS',false,true);if(kind==='text')document.execCommand('foreColor',false,value);else document.execCommand('hiliteColor',false,value);noteDraftDirty=true;const box=$('#selection-toolbar-menu');if(box){box.hidden=true;box.innerHTML=''}selectionMenuMode='';selectionToolbar();return}
  if(e.target.closest('[data-save-selected-keyword]')){const selected=activeEditorRange?.toString().trim();if(selected)openKeyword(selected);else toast('Select some text first.');return}
});
document.addEventListener('click',e=>{let editor=$('#note-editor')||$('#answer-editor');if(!editor)return;let swatch=e.target.closest('[data-highlight]');if(swatch){editor.focus();document.execCommand('styleWithCSS',false,true);document.execCommand('hiliteColor',false,swatch.dataset.highlight);if(activeNoteDraft)noteDraftDirty=true;return}let block=e.target.closest('[data-editor-action]');if(block){editor.focus();const level=Math.max(1,Math.min(4,Number(block.dataset.level)||1)),html=block.dataset.editorAction==='toggle'?`<details open class="note-toggle toggle-level-${level}"><summary>Toggle ${level}</summary><p><br></p></details><p><br></p>`:'<blockquote class="note-callout"><strong>Callout</strong><br><br></blockquote><p><br></p>';document.execCommand('insertHTML',false,html);if(activeNoteDraft)noteDraftDirty=true;return}let b=e.target.closest('[data-cmd]');if(!b)return;editor.focus();if(b.dataset.cmd==='createLink'){const url=window.prompt('Paste a link URL');if(url)document.execCommand('createLink',false,url)}else document.execCommand(b.dataset.cmd,false,b.dataset.val||null);if(activeNoteDraft)noteDraftDirty=true});
document.addEventListener('change',async e=>{if(e.target.matches('.tag-option input[type="checkbox"]')){e.target.closest('.tag-option').classList.toggle('is-selected',e.target.checked);return}if(e.target.id==='keyword-paper'||e.target.id==='keyword-subject'){let field=e.target.id==='keyword-paper'?'papers':'subjects',value=e.target.value,list=db.keywords.filter(k=>!value||k[field]?.includes(value));$('#keyword-grid').innerHTML=keywordCards(list);return}if(e.target.id==='paper-filter'){notePaper=e.target.value;return render()}if(e.target.id==='subject-filter'){noteSubject=e.target.value;return render()}if(e.target.id==='note-sort'){noteSort=e.target.value;return render()}if(e.target.matches('[data-pyqfilter]')){pyqFilters[e.target.dataset.pyqfilter]=e.target.value;let q=$('#pyq-search')?.value;render();if(q)$('#pyq-search').value=q;return}if(e.target.matches('[data-practice]')){if(!cloudReady){e.target.checked=false;return toast('Sign in to track your practice progress.')}let key=`${db.currentUser}:${e.target.dataset.practice}`,previous=db.practice[key],practicedAt=e.target.checked?new Date().toISOString():null;if(e.target.checked)db.practice[key]=practicedAt;else delete db.practice[key];try{await window.EdvantageData.setPractice(e.target.dataset.practice,e.target.checked,practicedAt)}catch(err){if(previous)db.practice[key]=previous;else delete db.practice[key];return toast(`Progress save failed: ${err.message}`)}save();render();return}if(e.target.id==='question-file'){return}});
document.addEventListener('input',e=>{if(e.target.id==='note-title'||e.target.id==='note-editor'){noteDraftDirty=true;const status=$('#save-status');if(status)status.textContent='Unsaved changes';if(e.target.id==='note-editor'){clearTimeout(noteEditorHistoryTimer);noteEditorHistoryTimer=setTimeout(pushEditorHistory,120)}}if(e.target.id==='note-search'){let q=e.target.value.toLowerCase();$$('.note-card').forEach(card=>card.style.display=(card.innerText.toLowerCase().includes(q)?'':'none'))}if(e.target.id==='pyq-search'){let caret=e.target.selectionStart;renderPyq();let input=$('#pyq-search');if(input){input.value=e.target.value;input.focus();input.setSelectionRange(caret,caret)}}if(e.target.id==='keyword-search'){let q=e.target.value.toLowerCase();$$('#keyword-grid .keyword-card').forEach(card=>card.style.display=card.innerText.toLowerCase().includes(q)?'':'none')}});
$('#global-search-trigger').addEventListener('click',openSearch);$('#theme-toggle')?.addEventListener('click',toggleTheme);$('#top-avatar')?.addEventListener('click',supabaseAccount);document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape'){closeModal();$('#search-overlay')?.remove()}});
function openSearch(){let old=$('#search-overlay');if(old)old.remove();let o=document.createElement('div');o.id='search-overlay';o.className='search-overlay open';o.innerHTML='<div class="search-box"><input id="global-search" placeholder="Search notes, keywords and questions…" autofocus><div class="search-results" id="global-results"><div class="field-hint" style="padding:10px">Start typing to search your workspace.</div></div></div>';document.body.append(o);let input=$('#global-search');input.focus();input.oninput=()=>{let q=input.value.toLowerCase();let items=[...db.notes.filter(n=>(n.title+' '+plainText(n.content)+' '+n.subjects.join(' ')).toLowerCase().includes(q)).map(n=>({type:'Note',title:n.title,sub:n.subjects.join(' · '),fn:()=>openNote(n.id)})),...db.keywords.filter(k=>(k.text+' '+k.subjects.join(' ')).toLowerCase().includes(q)).map(k=>({type:'Keyword',title:k.text,sub:k.subjects.join(' · '),fn:()=>setPage('keywords')})),...db.questions.filter(x=>x.text.toLowerCase().includes(q)).map(x=>({type:'PYQ',title:x.text,sub:`${x.year} · ${x.paper}`,fn:()=>setPage('pyq')}))];$('#global-results').innerHTML=items.length?items.slice(0,12).map((x,i)=>`<div class="search-result" data-search-result="${i}"><b>${esc(x.title)}</b><small>${esc(x.type)} · ${esc(x.sub)}</small></div>`).join(''):'<div class="field-hint" style="padding:10px">No matching results.</div>';o._items=items};o.addEventListener('click',e=>{let r=e.target.closest('[data-search-result]');if(r){o._items[Number(r.dataset.searchResult)].fn();o.remove()}else if(e.target===o)o.remove()})}
$('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});
updateUser();document.body.classList.toggle('dark',db.theme==='dark');(async()=>{try{const callback=await window.EdvantageAuth.consumeAuthRedirect();if(callback){authConfirmation=callback;page='authConfirmation';render();if(callback.status==='confirmed'){try{const session=await window.EdvantageAuth.session();if(session?.user)await activateSupabaseUser(session.user)}catch(e){toast(`Email verified, but the shared workspace could not load: ${e.message}`)}}return}const session=await window.EdvantageAuth.session();if(session?.user)await activateSupabaseUser(session.user);else render()}catch(e){authConfirmation={status:'error',message:e.message};page='authConfirmation';render()}})();
